.ds-ui-button {
  display: inline-flex;
  min-height: 2.75rem;
  width: fit-content;
  align-items: center;
  justify-content: center;
  border: 1px solid transparent;
  border-radius: var(--radius-small, 0.75rem);
  padding: 0.7rem 1rem;
  cursor: pointer;
  font: inherit;
  font-weight: 750;
  text-decoration: none;
  transition:
    background-color var(--motion-fast, 160ms) ease,
    border-color var(--motion-fast, 160ms) ease,
    box-shadow var(--motion-fast, 160ms) var(--ease-out, cubic-bezier(0.22, 1, 0.36, 1)),
    color var(--motion-fast, 160ms) ease,
    transform var(--motion-fast, 160ms) var(--ease-out, cubic-bezier(0.22, 1, 0.36, 1));
}
.ds-ui-button-primary {
  background: var(--teal-600, #087f83);
  color: var(--neutral-0, #ffffff);
  box-shadow: 0 0.55rem 1.2rem rgba(8, 127, 131, 0.2);
}
.ds-ui-button:disabled {
  cursor: not-allowed;
  opacity: 0.55;
  transform: none;
}.ds-focus:focus-visible {border-color:var(--color-focus, #07959b);outline:3px solid color-mix(in srgb,var(--color-focus, #07959b) 32%,transparent);outline-offset:2px;}
.ds-ui-button{font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;}
@media(max-width:36rem){.ds-ui-button{width:100%;}}@media(prefers-reduced-motion:reduce){.ds-ui-button{transition:none;}}

